text:
{
  "method": "Calculate the number of milk servings needed by multiplying the recommended calcium intake per kilogram of body weight by the typical body weight for each age group, then dividing by the amount of calcium provided in one serving of milk. The formula is: servings = (body_weight * calcium_per_kg) / calcium_per_serving. This divides the total calcium requirement by the calcium content per serving and is weighted by body weight and age‑specific calcium needs.",
  "calculations": [
    {
      "label": "Child_servings",
      "expression": "20*50/300"
    },
    {
      "label": "Elder_servings",
      "expression": "70*20/300"
    },
    {
      "label": "Difference_servings",
      "expression": "20*50/300-70*20/300"
    }
  ],
  "keyPoints": [
    "Young children are in a rapid growth phase and require more calcium and protein per kilogram of body weight for bone and tissue development.",
    "Milk is a dense source of calcium, vitamin D, and high‑quality protein, making it an efficient way to meet these higher per‑kg nutrient needs.",
    "Elderly individuals have lower growth demands and generally lower per‑kg calcium requirements, so their absolute milk needs are less, although they may need adequate calcium to maintain bone health."
  ]
}
